WITH hourly_avg AS (SELECT c.c_customer_sk, c.c_customer_id AS customer_id, td.t_hour AS hour, AVG(cs.cs_sales_price) AS avg_sales_price, COUNT(*) AS sales_cnt FROM catalog_sales cs JOIN time_dim td ON cs.cs_sold_time_sk = td.t_time_sk JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk GROUP BY c.c_customer_sk, c.c_customer_id, td.t_hour), ranked_hours AS (SELECT customer_id, hour, avg_sales_price, sales_cnt, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY avg_sales_price DESC) AS hour_rank FROM hourly_avg) SELECT customer_id, hour, avg_sales_price, sales_cnt, hour_rank FROM ranked_hours WHERE hour_rank <= 3 ORDER BY customer_id, hour_rank
